def report(area=None,game=None):
    if area is not None and area not in AREAS:raise FormatError('Unknown capability area')
    from . import availability
    return {'format':'aow4mod-capabilities/1','version':__version__,
            'areas':{area:AREAS[area]} if area else AREAS,
            'catalog_scope':'Implemented workflows; consult current_environment for this installation. Optional native flags and content-specific gates still apply.',
            'current_environment':availability.report(game),
            'runtime':{'python_optional_packages':{name:importlib.util.find_spec(name) is not None for name in ('polib','capstone','pefile')},
                       'steam_transport_platform_supported':os.name=='nt' and struct.calcsize('P')==8},
            'validation_boundary':'Static formats, evidence-bound fields and controlled filesystem/API workflows. No gameplay, save or multiplayer certification.'}
